fn update_timeline_after_parse(p) {
    let order_v = "缺少订单号"
    let order_ok = false
    let del_v = "缺少配送日期"
    let del_ok = false
    let ins_v = "缺少安装时间"
    let ins_ok = false
    for f in p.facts {
        if f.field == "order_id" { order_v = f.value; order_ok = true }
        if f.field == "delivery_date" { del_v = "预计 " + f.value; del_ok = true }
        if f.field == "installation_time" { ins_v = fmt_iso(f.value); ins_ok = true }
    }
    if order_ok { timeline = timeline_update(timeline, "order", order_v, "done") } else { timeline = timeline_update(timeline, "order", order_v, "pending") }
    if del_ok { timeline = timeline_update(timeline, "delivery", del_v, "alert") } else { timeline = timeline_update(timeline, "delivery", del_v, "pending") }
    if ins_ok { timeline = timeline_update(timeline, "installation", ins_v, "alert") } else { timeline = timeline_update(timeline, "installation", ins_v, "pending") }
}

// 解析入口（app.js parse）
fn do_parse() {
    let is_supplement = machine.state == "NeedInfo"
    if !is_supplement {
        machine = {state: "Idle" replan: 0}
        apply_event("paste_notice")
    }
    let result = parse_notice(ui.input_area.text(), "pasted_notice_01", "2026-09-27")
    if is_supplement {
        parsed = merge_parsed(parsed, result)
    } else {
        parsed = result
        audit = []
        last_action_key = ""
    }
    plans = []
    selected_plan = 0
    update_timeline_after_parse(parsed)
    if parsed.errors.len() > 0 and parsed.facts.len() == 0 {
        apply_event("parse_failed")
        set_msg("fail", "解析失败：" + join_str(parsed.errors, "；"))
    } else if parsed.errors.len() > 0 or parsed.missing.len() > 0 {
        if machine.state != "NeedInfo" { apply_event("need_info") }
        let what = join_str(parsed.missing, "、")
        if what == "" { what = join_str(parsed.errors, "；") }
        set_msg("warn", "需要补充：" + what)
    } else {
        if machine.state == "NeedInfo" { apply_event("parsed") }
        apply_event("parsed")
        let delivery_num = -1
        let install_num = -1
        for f in parsed.facts {
            if f.field == "delivery_date" { delivery_num = date_num(f.value) }
            if f.field == "installation_time" { install_num = date_num(f.value) }
        }
        if delivery_num > 0 and install_num > 0 and delivery_num >= install_num {
            apply_event("conflict_found")
        }
        plans = build_plans(parsed)
        apply_event("plan_ready")
        set_msg("ok", "已解析。配送日期不早于原安装日期，请确认新的安排。")
    }
    save_state()
    render_all()
}

// 执行方案（app.js executePlan）
fn execute_plan(simulate_failure) {
    if plans.len() == 0 { return }
    let plan = plans[selected_plan]
    let action_key = compute_idempotency_key(parsed, plan)
    if last_action_key == action_key and machine.state != "Partial" {
        let row = {time: now_hhmm() action: "重复确认" result: "已存在相同操作，未重复创建。" kind: "warn" basedOn: plan.refs}
        let next_audit = [row]
        for r in audit { next_audit.push(r) }
        audit = next_audit
        save_state()
        render_audit()
        return
    }
    let validation = validate_plan({request_id: 1 options: [plan]}, parsed.facts, SCHEDULE)
    if !validation.valid {
        set_msg("fail", "方案校验未通过：" + join_str(validation.errors, "；"))
        return
    }
    let is_retry = machine.state == "Partial"
    if is_retry { apply_event("plan_ready") }
    apply_event("user_confirmed")
    let now = now_hhmm()
    let results = []
    for a in plan.actions {
        let is_reminder = a.type == "create_reminder"
        let failed = simulate_failure and is_reminder
        let run_it = true
        if is_retry and !is_reminder { run_it = false }
        if run_it {
            results.push(apply_action(a, now, plan.refs, action_key, is_reminder and !failed, !failed, "提醒创建失败，已进入部分成功状态。"))
        }
    }
    let settlement = settle_actions(results)
    if settlement.status == "partial" {
        apply_event("partial_actions_succeeded")
        set_msg("warn", "部分成功：改期已写入本地时间线，复查提醒尚未创建。可重试或选择规则兜底。")
    } else if settlement.status == "failed" {
        apply_event("all_actions_failed")
        set_msg("fail", "执行失败：本地动作未完成，请选择规则兜底或重试。")
    } else {
        apply_event("all_actions_succeeded")
        apply_event("verify_ok")
        set_msg("ok", "执行完成：本地时间线已更新，复查提醒已创建，结果已核验。")
    }
    save_state()
    render_all()
}

fn reject_plan() {
    apply_event("user_rejected")
    set_msg("warn", "已放弃本次安排，可重新粘贴通知或手动整理。")
    save_state()
    render_all()
}

fn manual_plan() {
    apply_event("manual_plan")
    set_msg("ok", "已采用手动方案，重规划计数已清零。请确认执行。")
    save_state()
    render_all()
}



